import{_ as t,o,c as a,a3 as s}from"./chunks/framework.CMTNx0DQ.js";const u=JSON.parse('{"title":"Every credential resolves to one caller with scopes","description":"","frontmatter":{"status":"accepted","date":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0020-every-credential-resolves-to-one-caller.md","filePath":"docs/adr/0020-every-credential-resolves-to-one-caller.md"}'),r={name:"docs/adr/0020-every-credential-resolves-to-one-caller.md"};function n(i,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="every-credential-resolves-to-one-caller-with-scopes" tabindex="-1">Every credential resolves to one caller with scopes <a class="header-anchor" href="#every-credential-resolves-to-one-caller-with-scopes" aria-label="Permalink to &quot;Every credential resolves to one caller with scopes&quot;">​</a></h1><p>The API will be called by the phone apps first, then the website, a person&#39;s own scripts and the MCP server, and later third-party apps (<a href="https://github.com/tkint/coach-poulpy/issues/228" target="_blank" rel="noreferrer">#228</a>). So authentication and authorization are kept apart: each way of signing in only answers &quot;who is calling, with which rights&quot;, and the routes only ask &quot;does this caller hold the scope, and is it their data&quot;. Adding a mechanism, or moving token issuing to an identity provider, is one new authenticator; no route changes.</p><h2 id="how-a-request-is-checked" tabindex="-1">How a request is checked <a class="header-anchor" href="#how-a-request-is-checked" aria-label="Permalink to &quot;How a request is checked&quot;">​</a></h2><ol><li><strong>Authenticate.</strong> One http4k filter reads the credential (an <code>Authorization: Bearer</code> token, or the website&#39;s cookie), picks the authenticator for that kind of token by its prefix, and stores a <strong>caller</strong> on the request: the account, the client holding the credential (the app, the website, a personal access token, a third-party app) and its granted scopes. No credential gives an anonymous caller, which only public routes accept; a bad or expired one is a 401.</li><li><strong>Check the scope.</strong> Each route declares the scopes it needs, next to it in the http4k contract, so the OpenAPI description shows them. A missing scope is a 403. Scopes are <code>resource:action</code>: <code>workouts:read</code>, <code>workouts:write</code>, <code>plans:read</code>, <code>plans:write</code>, <code>sessions:read</code>, <code>sessions:write</code>, <code>profile:read</code>, <code>profile:write</code>, and <code>sync</code> for the phones&#39; push and pull.</li><li><strong>Check ownership.</strong> Every repository call takes the caller&#39;s account id, so a query only sees that account&#39;s rows. Coach access is checked against an active coach link on each request.</li></ol><p>Some actions are never grantable to a token or an outside app: changing the email or password, deleting the account, creating tokens, granting a coach. They need a first-party sign-in. Admin (<a href="https://github.com/tkint/coach-poulpy/issues/26" target="_blank" rel="noreferrer">#26</a>) is a role on the account, not a scope anyone can ask for. <code>/health</code> and the catalog (<a href="https://github.com/tkint/coach-poulpy/issues/27" target="_blank" rel="noreferrer">#27</a>) are public.</p><h2 id="tokens-are-opaque-and-api-v1-me-says-who-you-are" tabindex="-1">Tokens are opaque, and <code>/api/v1/me</code> says who you are <a class="header-anchor" href="#tokens-are-opaque-and-api-v1-me-says-who-you-are" aria-label="Permalink to &quot;Tokens are opaque, and `/api/v1/me` says who you are&quot;">​</a></h2><p>The server issues its own tokens for now. They are random 256-bit values with a readable prefix (<code>cp_at_</code> access, <code>cp_rt_</code> refresh, <code>cp_pat_</code> personal access token) so secret scanners spot a leak; Postgres keeps only their SHA-256. A client that wants to know who it is calls <code>GET /api/v1/me</code>, which returns the account id, email, role, the client and the scopes of the token used.</p><table tabindex="0"><thead><tr><th>Who</th><th>Signs in with</th><th>Holds</th><th>Scopes</th><th>When</th></tr></thead><tbody><tr><td>Phone app</td><td>Email and password (Argon2id), Sign in with Apple or Google (ID token verified by the server)</td><td>15-minute access token and a rotating refresh token, in Keychain or Android Keystore</td><td>All user scopes and <code>sync</code></td><td>Phase 3 (<a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>)</td></tr><tr><td>Website</td><td>The same sign-in</td><td>The same tokens, in an HttpOnly, Secure, SameSite cookie</td><td>All user scopes</td><td>Phase 4</td></tr><tr><td>A person&#39;s scripts, the MCP server</td><td>A personal access token made in Settings: named, scoped, with an expiry, shown once</td><td><code>Authorization: Bearer cp_pat_…</code></td><td>Those picked when making it</td><td>With #228</td></tr><tr><td>Third-party apps</td><td>OAuth 2.1 authorization code with PKCE, approved on a consent page</td><td>Access and refresh tokens tied to that app</td><td>Those approved</td><td>Later, with #228</td></tr></tbody></table><ul><li><strong>Refresh tokens rotate.</strong> Each use returns a new one, and reusing an old one revokes its whole family.</li><li><strong>Everything is revocable and visible.</strong> Settings lists devices, personal tokens and connected apps with their last use.</li><li><strong>Health data read by tokens is logged.</strong> Personal tokens and third-party apps leave an audit row per request on sessions and profile data.</li><li><strong>The website&#39;s cookie is guarded against CSRF</strong> by SameSite and an <code>Origin</code> check on every write, and CORS allows only Coach Poulpy&#39;s own sites.</li><li><strong>The MCP server needs nothing new.</strong> MCP authorizes with OAuth 2.1 and PKCE plus a protected-resource document under <code>/.well-known/</code>, which this design serves.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Signed JWTs as access tokens.</strong> They carry the caller&#39;s details and need no lookup, but anyone can read them, and they cannot be revoked before they expire. With one server a database lookup per request is cheap and revocation is instant, so <code>/me</code> gives the details instead. If an identity provider takes over issuing, its JWTs get their own authenticator.</li><li><strong>An identity provider now (Keycloak, Zitadel, Auth0).</strong> Keycloak needs more memory than the machine has left beside the server (<a href="./0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>), and a hosted one costs money and adds a processor of health-adjacent data. The caller model keeps that move open.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The server owns password hashing, token storage, rotation and revocation, and later the OAuth endpoints (<code>http4k-security-oauth</code> provides the pieces).</li><li>Every authenticated request costs one indexed lookup in the token table.</li><li>Every route declares its scopes or is marked public, and a test checks that none is left out.</li></ul>',13)])])}const k=t(r,[["render",n]]);export{u as __pageData,k as default};
